</div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>document.querySelectorAll('[data-confirm]').forEach(x=>x.addEventListener('click',e=>{if(!confirm(x.dataset.confirm))e.preventDefault()}));const kode=document.querySelector('input[name="kode"]');if(kode){kode.readOnly=true;kode.placeholder='Otomatis dibuat saat disimpan';if(!kode.value)kode.value='Otomatis dibuat';}</script></body></html>
